EXTRA_CSS = '@media(min-width:761px){\n.bdt-hero{margin:10px auto 0;min-height:280px;border:0;box-shadow:0 0 0 1px rgba(255,255,255,.07),0 18px 40px -20px rgba(0,0,0,.9)}\n.bdt-hero::before{background:linear-gradient(180deg,rgba(5,11,9,.55) 0%,rgba(5,11,9,0) 28%),linear-gradient(90deg,rgba(5,11,9,.93) 0%,rgba(5,11,9,.78) 42%,rgba(5,11,9,.22) 100%) !important}\n.bdt-hero .bdt-hin{padding:24px 34px 28px}\n.tabs{padding:12px 18px}\n#v-overview .frame.tph{max-height:none;height:var(--fh,460px);aspect-ratio:auto}\n#v-overview .frame.tph+*{margin-top:0}\n#v-overview .hero{margin-bottom:34px}\n}\n@media(max-width:760px){.tabs button img.tico,.tabs button img.tico.gob{height:24px;margin:-1px 0}}\n@media(min-width:761px){.tabs button img.tico,.tabs button img.tico.gob{height:26px;margin:-1px 0}.tabs button span{white-space:nowrap}}\n@media(min-width:761px){.tabs{display:flex;flex-wrap:nowrap;gap:5px;padding:12px 18px}\n.tabs button{flex:1 1 0;min-width:0;padding:10px 2px 8px;letter-spacing:0}.tabs button span{display:block}}'
EXTRA_JS = '<script>(function(){\nconst R={accommodation:\'Kennels\',courses:\'Courses\',announcement:\'Preview\',leaderboard:\'Standings\'};\ndocument.querySelectorAll(\'#tabs button\').forEach(b=>{const n=R[b.dataset.k];if(!n)return;const sp=b.querySelector(\'span\');(sp||b).textContent=n});\nconst tb=document.querySelector(\'#tabs button[data-k="trophies"]\'),rb=document.querySelector(\'#tabs button[data-k="rydercup"]\');\nconst ti=tb&&tb.querySelector(\'img.tico\');\nif(ti){const rc=ti.src;ti.src=\'data:image/png;base64,\';ti.classList.add(\'gob\');\n if(rb){const sv=rb.querySelector(\'svg\');const im=document.createElement(\'img\');im.className=\'tico\';im.alt=\'\';im.src=rc;if(sv)sv.replaceWith(im);else rb.prepend(im)}}\nfunction fitTabs(){const t=document.getElementById(\'tabs\');const bs=[...t.querySelectorAll(\'button\')];bs.forEach(b=>b.style.fontSize=\'\');\n if(matchMedia(\'(max-width:760px)\').matches)return;let fs=11;\n const over=()=>bs.some(b=>{const sp=b.querySelector(\'span\');return sp&&sp.scrollWidth>b.clientWidth-4});\n while(over()&&fs>8.5){fs-=.25;bs.forEach(b=>b.style.fontSize=fs+\'px\')}}\nfitTabs();addEventListener(\'resize\',fitTabs);\nlet fold=0;\nfunction fit(){const f=document.querySelector(\'#v-overview .frame.tph\');if(!f)return;\n if(matchMedia(\'(max-width:760px)\').matches){f.style.removeProperty(\'--fh\');return}\n const vb=fold||innerHeight;const top=f.getBoundingClientRect().top+scrollY;\n f.style.setProperty(\'--fh\',Math.max(260,Math.min(680,vb-top-16))+\'px\')}\ntry{const s=document.createElement(\'div\');s.style.cssText=\'position:absolute;left:0;top:0;width:1px;height:\'+Math.max(document.documentElement.scrollHeight,3000)+\'px;pointer-events:none;visibility:hidden\';document.body.appendChild(s);\n const th=[];for(let i=0;i<=100;i++)th.push(i/100);\n const io=new IntersectionObserver(e=>{const r=e[0].intersectionRect;if(r&&r.height>0&&scrollY<5&&r.top<=1){fold=r.bottom;fit()}},{threshold:th});io.observe(s);setTimeout(()=>{try{io.disconnect()}catch(e){}s.remove()},6000)}catch(e){}\nfit();addEventListener(\'resize\',fit);document.documentElement.classList.add(\'lg-ready\');})();</script>'


GATE = ("html:not(.lg-ready) #tabs,html:not(.lg-ready) #views{visibility:hidden}")
GATE_JS = "<script>setTimeout(function(){document.documentElement.classList.add('lg-ready')},2500)</script><style id=\"bdt-seg-fix\">.seg:not(.on){color:#E6ECE7 !important}</style>"


def _ord(n):
    n = int(n)
    return f"{n}{'th' if 10 <= n % 100 <= 20 else {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')}"


def header_details(html, flag='', strap='', start=None, end=None, rc_num=None):
    """Write the flag, strapline and dates into the header at build time so nothing moves while the page loads."""
    import re
    dates = ''
    if start and end:
        if (start.year, start.month) == (end.year, end.month):
            dates = f"{start.day} \u2013 {end.day} {end:%B %Y}"
        elif start.year == end.year:
            dates = f"{start.day} {start:%B} \u2013 {end.day} {end:%B %Y}"
        else:
            dates = f"{start.day} {start:%B %Y} \u2013 {end.day} {end:%B %Y}"
    if rc_num:
        try:
            dates += f" \u00b7 {_ord(rc_num)} Big Dogs Ryder Cup"
        except (TypeError, ValueError):
            pass
    cal = ('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'
           '<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>')
    fl = f'<img class="tf" src="https://flagcdn.com/w80/{flag}.png" alt="">' if flag else ''
    extra = (f'<div class="bdt-strap">{strap}</div>' if strap else '') + (f'<div class="bdt-when">{cal}<span>{dates}</span></div>' if dates else '')
    html = re.sub(r'(<div class="bdt-t2">)(.*?)(</div>)', lambda m: m.group(1) + fl + m.group(2) + m.group(3) + extra, html, count=1)
    return html


def apply(html):
    html = html.replace('</head>', '<style id="bdt-layout-g">' + CSS + EXTRA_CSS + GATE + '</style>' + GATE_JS + '</head>', 1)
    return html.replace('</body>', JS + EXTRA_JS + '</body>', 1)
